  expires_at: string;
  id: string;
  /** Exactly what it was given. */
  input: Json;
  /** The rule's message, with the facts filled in. */
  message: string | null;
  /** The policy point that asked for approval. */
  point: string;
  requested_at: string;
  /** Who asked. */
  requested_by: string;
  /** Their name. */
